import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Wifi, Download, Upload, Activity, MapPin, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';

function App() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  // Ping test - measures latency (multiple attempts for accuracy)
  const measurePing = async () => {
    try {
      const pings = [];
      
      // Run 3 ping tests and take the average
      for (let i = 0; i < 3; i++) {
        const start = performance.now();
        await fetch(`${API_BASE}/api/ping`, { cache: 'no-store' });
        const end = performance.now();
        pings.push(end - start);
      }
      
      // Return average ping
      const avgPing = Math.floor(pings.reduce((a, b) => a + b) / pings.length);
      return avgPing;
    } catch (err) {
      console.error('Ping test failed:', err);
      return 0;
    }
  };

  // Download test - parallel connections for accuracy
  const measureDownloadSpeed = async () => {
    try {
      const CHUNK_SIZE = 5 * 1024 * 1024; // 5MB chunks
      const NUM_PARALLEL = 4; // 4 parallel connections
      let totalBytes = 0;
      let totalTime = 0;

      // Run test 3 times and take average for consistency
      for (let attempt = 0; attempt < 2; attempt++) {
        const testStart = performance.now();

        // Run parallel downloads
        const promises = Array.from({ length: NUM_PARALLEL }).map(async () => {
          try {
            const response = await fetch(
              `${API_BASE}/api/download?size=${CHUNK_SIZE}&t=${Date.now()}`,
              {
                cache: 'no-store',
                headers: {
                  'Pragma': 'no-cache',
                  'Cache-Control': 'no-cache',
                },
              }
            );

            if (!response.ok) throw new Error('Download failed');
            return await response.arrayBuffer();
          } catch (err) {
            console.error('Parallel download failed:', err);
            return new ArrayBuffer(0);
          }
        });

        const results = await Promise.all(promises);
        const chunkBytes = results.reduce((sum, buf) => sum + buf.byteLength, 0);
        const testEnd = performance.now();

        totalBytes += chunkBytes;
        totalTime += (testEnd - testStart) / 1000; // Convert to seconds
      }

      // Calculate Mbps with safeguards
      if (totalTime === 0) totalTime = 0.1; // Prevent division by zero
      const Mbps = (totalBytes * 8) / totalTime / 1000000;
      
      // Cap unrealistic values
      return Math.min(Math.max(Mbps, 0), 10000); // Between 0-10000 Mbps
    } catch (err) {
      console.error('Download test failed:', err);
      return 0;
    }
  };

  // Upload test - realistic upload measurement
  const measureUploadSpeed = async () => {
    try {
      const CHUNK_SIZE = 2 * 1024 * 1024; // 2MB chunks
      const NUM_UPLOADS = 2; // 2 sequential uploads
      let totalBytes = 0;
      let totalTime = 0;

      for (let i = 0; i < NUM_UPLOADS; i++) {
        // Create random data once, reuse for consistent timing
        const data = new Uint8Array(CHUNK_SIZE);
        crypto.getRandomValues(data);

        const start = performance.now();

        try {
          const response = await fetch(`${API_BASE}/api/upload-large?t=${Date.now()}`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/octet-stream',
            },
            body: data,
          });

          if (!response.ok) throw new Error('Upload failed');
          await response.json();
        } catch (err) {
          console.error('Upload attempt failed:', err);
          continue;
        }

        const end = performance.now();
        totalBytes += data.byteLength;
        totalTime += (end - start) / 1000; // Convert to seconds
      }

      // Calculate Mbps with safeguards
      if (totalTime === 0) totalTime = 0.1; // Prevent division by zero
      const Mbps = (totalBytes * 8) / totalTime / 1000000;
      
      // Cap unrealistic values
      return Math.min(Math.max(Mbps, 0), 10000); // Between 0-10000 Mbps
    } catch (err) {
      console.error('Upload test failed:', err);
      return 0;
    }
  };

  const runTest = async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      // Step 1: Ping test
      const pingResult = await measurePing();
      setPing(pingResult);

      // Step 2: Download speed test
      const downloadSpeed = await measureDownloadSpeed();

      // Step 3: Upload speed test
      const uploadSpeed = await measureUploadSpeed();

      // Animate to final values
      let current = 0;
      const downloadFinal = Number(downloadSpeed.toFixed(2));
      const uploadFinal = Number(uploadSpeed.toFixed(2));
      const step = Math.max(downloadFinal, uploadFinal) / 60;

      const interval = setInterval(() => {
        current += step;

        const downSpeed = Math.min(current, downloadFinal);
        const upSpeed = Math.min(current, uploadFinal);

        if (current >= Math.max(downloadFinal, uploadFinal)) {
          current = Math.max(downloadFinal, uploadFinal);
          clearInterval(interval);
          setTesting(false);
        }

        setDownload(downSpeed.toFixed(2));
        setUpload(upSpeed.toFixed(2));

        setHistory((prev) => [
          ...prev,
          {
            time: prev.length,
            speed: Number(downSpeed.toFixed(2)),
          },
        ]);
      }, 80);
    } catch (err) {
      console.error('Speed test error:', err);
      setTesting(false);
      alert('Speed test failed. Make sure backend server is running on port 5000');
    }
  };

  useEffect(() => {
    // Auto-run test on component mount
    const timer = setTimeout(() => runTest(), 500);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="main-bg">
      <div className="container py-4">
        {/* HEADER */}
        <div className="topbar">
          <div className="d-flex align-items-center gap-3">
            <Wifi color="#00f7ff" size={34} />
            <h1 className="logo-text">SPEED CHECKER</h1>
          </div>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'TESTING...' : 'RUN TEST'}
          </button>
        </div>

        {/* TOP CARDS */}
        <div className="row g-4 mt-1">
          <div className="col-6 col-lg-3">
            <MiniCard title="Download" value={`${download} Mbps`} icon={<Download />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Upload" value={`${upload} Mbps`} icon={<Upload />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Ping" value={`${ping} ms`} icon={<Activity />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Status" value={testing ? 'Testing' : 'Stable'} icon={<Wifi />} />
          </div>
        </div>

        {/* MAIN PANEL */}
        <div className="glass-panel mt-4">
          {/* SPEED DISPLAY */}
          <motion.div
            key={download}
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="speed-display"
          >
            <h1 className="speed-value">{download}</h1>
            <div className="speed-unit">Mbps</div>
          </motion.div>

          {/* GRAPH */}
          <div className="chart-box">
            <ResponsiveContainer width="100%" height={300}>
              <AreaChart data={history}>
                <defs>
                  <linearGradient id="colorSpeed" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#00f7ff" stopOpacity={0.8} />
                    <stop offset="95%" stopColor="#00f7ff" stopOpacity={0} />
                  </linearGradient>
                </defs>

                <XAxis dataKey="time" stroke="#6ecfff" />
                <Tooltip />

                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="url(#colorSpeed)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* BOTTOM INFO */}
        <div className="row g-4 mt-1">
          <div className="col-md-4">
            <InfoCard title="Server" value="Local" icon={<Server />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Location" value="Your PC" icon={<MapPin />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Connection" value="Accurate" icon={<Wifi />} />
          </div>
        </div>

        {/* FOOTER */}
        <footer className="footer-section">
          <div className="footer-links">
            <a href="/PRIVACY_POLICY.md" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
            <span className="separator">|</span>
            <a href="/TERMS_OF_SERVICE.md" target="_blank" rel="noopener noreferrer">Terms of Service</a>
            <span className="separator">|</span>
            <a href="/DISCLAIMER.md" target="_blank" rel="noopener noreferrer">Disclaimer</a>
            <span className="separator">|</span>
            <a href="/ABOUT_US.md" target="_blank" rel="noopener noreferrer">About Us</a>
            <span className="separator">|</span>
            <a href="/COOKIE_POLICY.md" target="_blank" rel="noopener noreferrer">Cookie Policy</a>
          </div>
          <p className="footer-copyright">© 2026 Speed Checker. All rights reserved. Powered by Speed Checker</p>
        </footer>
      </div>
    </div>
  );
}

function MiniCard({ title, value, icon }) {
  return (
    <div className="mini-card">
      <div className="mini-icon">{icon}</div>
      <div className="mini-title">{title}</div>
      <div className="mini-value">{value}</div>
    </div>
  );
}

function InfoCard({ title, value, icon }) {
  return (
    <div className="info-card">
      <div className="info-icon">{icon}</div>
      <div className="info-title">{title}</div>
      <div className="info-value">{value}</div>
    </div>
  );
}

export default App;
